		version: 1,
		lastTuiActivityAt: 0,
		...readRecord(file, agentDir),
		...update,
		sessionFile: canonicalSessionPath(file),
		sessionId: manager.getSessionId(),
		cwd: manager.getCwd(),
		sessionDir: manager.getSessionDir(),
	};
